arguments.command:
cd /tmp/sv-71f9f1380e7f4868a26fc9c940c254ed && \
# Now try to get symbols for the other two libraries
# Try downloading the actual .so with symbols from symbol server (non-dbg)
curl -sfL -o libSystem.Native.so "https://msdl.microsoft.com/download/symbols/libSystem.Native.so/elf-buildid-7a3b5c9d1e4f6082a3c5d7e9f1b2d4a6c8e0f213/libSystem.Native.so" 
file libSystem.Native.so 2>/dev/null && \
python3 << 'EOF'
import subprocess

# Use the downloaded .so which might have symbol table
for lib, addrs in [
    ("libSystem.Native.so", [0x8f14, 0x12a48]),
]:
    result = subprocess.run(['llvm-nm-18', '--defined-only', lib], capture_output=True, text=True)
    if result.returncode != 0:
        # Try dynamic symbols
        result = subprocess.run(['llvm-nm-18', '--dynamic', '--defined-only', lib], capture_output=True, text=True)

    symbols = []
    for line in result.stdout.strip().split('\n'):
        parts = line.split()
        if len(parts) >= 3:
            try:
                addr = int(parts[0], 16)
                symbols.append((addr, parts[2]))
            except ValueError:
                pass
    symbols.sort()

    for target in addrs:
        before = None
        for addr, name in symbols:
            if addr <= target:
                before = (addr, name)
            else:
                break
        if before:
            offset = target - before[0]
            print(f"{lib} 0x{target:x} => {before[1]}+0x{offset:x}")
        else:
            print(f"{lib} 0x{target:x} => ???")
EOF

